export function SourcePanel({
  primarySourceTitle = "{{primarySourceTitle}}",
  accent = "{{accent}}",
  collapsed = {{collapsed}},
  showDomains = {{showDomains}},
}) {
  const sources = [
    { title: primarySourceTitle, domain: "internal-reports.example" },
    { title: "API rate limit changelog", domain: "docs.example.com" },
    { title: "Support ticket #4821", domain: "support.example.com" },
  ];
  return (
    <details open={!collapsed} style={{ maxWidth: 420, border: "1.5px solid #24143026", borderRadius: 10,
      padding: "4px 14px", background: "#FAF7F2", color: "#241430", fontFamily: "system-ui, sans-serif", fontSize: 14 }}>
      <summary style={{ cursor: "pointer", padding: "10px 0", fontWeight: 600, listStyle: "none" }}>
        Sources (3)
      </summary>
      <ul style={{ listStyle: "none", margin: 0, padding: "0 0 10px", display: "flex", flexDirection: "column", gap: 8 }}>
        {sources.map((s) => (
          <li key={s.title} style={{ display: "flex", alignItems: "baseline", gap: 8 }}>
            <span aria-hidden="true" style={{ flex: "none", width: 6, height: 6, borderRadius: "50%", background: accent, alignSelf: "center" }} />
            <span style={{ flex: 1, minWidth: 0 }}>{s.title}</span>
            {showDomains && <span style={{ flex: "none", fontSize: 12, color: "#24143080" }}>{s.domain}</span>}
          </li>
        ))}
      </ul>
    </details>
  );
}
